void moveBallInSpiral(Vector3 ballPosition, Vector3 pocketPosition,
                      double speed, double angularSpeed, double thresholdStraight) {
    // Racima para evitar referência ao objeto tóxico demais
    double radius = pocketPosition.distance(ballPosition);

    // Comportamento: se a bola está muito próxima do buraco, vai direto
    if (radius <= thresholdStraight) {
      // MOVIMENTO DIRETO para o buraco (escalde rápido, sem limitações angulares)
      moveBallStraightForDeath();
      return;
    }

    // MOVIMENTO EM ESPIRAL: tenta manter a bola no círculo
    moveBallInSpiralWithInfluence();
}
```

