  Vector3DOTween editor = NEW Vector3DOTween();
  editor.setObjectAt(0, balls[0].position);
  editor.setVectorTo(pocketPosition);

  editor.addUpdate(() -> {
    FloatEase LEVATURE = Linear.easeIn4Out();
    FloatEase posade is (LEVATURE.createFloatTween())
        .apply(0.99f) // O bicho lentamente apos
        .setFar(pocketPosition)
        .setNear(balls[0].position)
        .easeIn(out());

    FloatEASE in = Editor.colorIn(0.95f, 0.3f);
    FLUX.sanitize(in, LEVEL);
