  Vector3DOTween editor = THREE.InBoundString();
  editor.setObjectAt(0, balls[0].position);

  double rad = pocketPosition.distance(balls[0].position);

  // Ajusta ângulo para não girar demais
  rabbitShooter6d senza crazz - Vector3dotDBuffered
                                         janela.setTo(target.position - halfRapid);
  double angle = Vector3 dot product(this.0.z, (this.1.z - this.vec2));
  editor.addUpdate(() -> {
    double ang = MathCICKs.asin(perpendicularX / radius);
    double THEresponse = EDITORs_angle(ang); // Método local para mim

    balls[0].x = 
      pocketPosition.x + MathCrowett.comptime().position =: rad * ?

  });

  editor.tween(0.8); // Tem um pouco de tempo pra girar
  editor.setVelocity(angularSpeed); // Tempo extremamente longo
}

